include "globals.mzn";

% Five houses numbered 1 to 5
int: N = 5;
set of int: HOUSE = 1..N;

% Enums for each attribute category
enum NATIONALITY = {Englishman, Spaniard, Ukrainian, Norwegian, Japanese};
enum COLOR = {red, green, ivory, yellow, blue};
enum PET = {dog, snails, fox, horse, zebra};
enum DRINK = {coffee, tea, milk, orange_juice, water};
enum CIGARETTE = {Old_Gold, Kools, Chesterfields, Lucky_Strike, Parliaments};

% Decision variables - arrays indexed by house position
array[HOUSE] of var NATIONALITY: nationality;
array[HOUSE] of var COLOR: color;
array[HOUSE] of var PET: pet;
array[HOUSE] of var DRINK: drink;
array[HOUSE] of var CIGARETTE: cigarette;

% All attributes must be different across houses
constraint alldifferent(nationality);
constraint alldifferent(color);
constraint alldifferent(pet);
constraint alldifferent(drink);
constraint alldifferent(cigarette);

% 1. The Englishman lives in the red house.
constraint forall(h in HOUSE)(
  (nationality[h] = Englishman) <-> (color[h] = red)
);

% 2. The Spaniard owns the dog.
constraint forall(h in HOUSE)(
  (nationality[h] = Spaniard) <-> (pet[h] = dog)
);

% 3. Coffee is drunk in the green house.
constraint forall(h in HOUSE)(
  (drink[h] = coffee) <-> (color[h] = green)
);

% 4. The Ukrainian drinks tea.
constraint forall(h in HOUSE)(
  (nationality[h] = Ukrainian) <-> (drink[h] = tea)
);

% 5. The green house is immediately to the right of the ivory house.
constraint exists(h in 1..N-1)(
  color[h] = ivory /\ color[h+1] = green
);

% 6. The Old Gold smoker owns snails.
constraint forall(h in HOUSE)(
  (cigarette[h] = Old_Gold) <-> (pet[h] = snails)
);

% 7. Kools are smoked in the yellow house.
constraint forall(h in HOUSE)(
  (cigarette[h] = Kools) <-> (color[h] = yellow)
);

% 8. Milk is drunk in the middle house.
constraint drink[3] = milk;

% 9. The Norwegian lives in the first house.
constraint nationality[1] = Norwegian;

% 10. The man who smokes Chesterfields lives in the house next to the man with the fox.
constraint exists(h in HOUSE)(
  cigarette[h] = Chesterfields /\
  exists(h2 in HOUSE)(
    pet[h2] = fox /\ abs(h - h2) = 1
  )
);

% 11. Kools are smoked in the house next to the house where the horse is kept.
constraint exists(h in HOUSE)(
  cigarette[h] = Kools /\
  exists(h2 in HOUSE)(
    pet[h2] = horse /\ abs(h - h2) = 1
  )
);

% 12. The Lucky Strike smoker drinks orange juice.
constraint forall(h in HOUSE)(
  (cigarette[h] = Lucky_Strike) <-> (drink[h] = orange_juice)
);

% 13. The Japanese smokes Parliaments.
constraint forall(h in HOUSE)(
  (nationality[h] = Japanese) <-> (cigarette[h] = Parliaments)
);

% 14. The Norwegian lives next to the blue house.
constraint exists(h in HOUSE)(
  nationality[h] = Norwegian /\
  exists(h2 in HOUSE)(
    color[h2] = blue /\ abs(h - h2) = 1
  )
);

solve satisfy;

include "globals.mzn";

% Houses numbered 1 to 3
set of int: HOUSE = 1..3;

% Enums for colors and animals
enum COLOR = {Blue, Red, Green};
enum ANIMAL = {Dog, Cat, Zebra};

% Decision variables
array[HOUSE] of var COLOR: color;
array[HOUSE] of var ANIMAL: animal;

% Each house has a unique color and animal
constraint alldifferent(color);
constraint alldifferent(animal);

% Clue 1: The Cat lives in the Red House
constraint exists(h in HOUSE)(color[h] = Red /\ animal[h] = Cat);

% Clue 2: The Red House is the middle house
constraint color[2] = Red;

% Clue 3: The Blue House is directly to the left of the Red House
constraint exists(h in HOUSE)(color[h] = Blue /\ h + 1 <= 3 /\ color[h + 1] = Red);

% Clue 4: The Dog lives in the Blue House
constraint exists(h in HOUSE)(color[h] = Blue /\ animal[h] = Dog);

solve satisfy;

enum Move = {Paper, Rock, Scissors};

var Move: you;
var Move: opponent;

constraint opponent = Rock;

constraint (you = Paper /\ opponent = Rock) \/
           (you = Rock /\ opponent = Scissors) \/
           (you = Scissors /\ opponent = Paper);

solve satisfy;

