include "globals.mzn";

% Entities
enum ENTITY = {Pedestrian, NorthCar, EastCar, SouthCar, WestCar};

% Decision variables: order in which each entity goes through (1 = first, 5 = last)
array[ENTITY] of var 1..5: order;

% All entities go in different positions
constraint alldifferent(order);

% Arrival times (lower = earlier)
array[ENTITY] of var 1..3: arrival;

% Rule 1: Pedestrian crosses eastern crosswalk, so goes before East car
constraint order[Pedestrian] < order[EastCar];

% Clue 5: Pedestrian and East car arrive at same moment
constraint arrival[Pedestrian] = arrival[EastCar];

% Clue 6: South car arrives before Pedestrian and East car
constraint arrival[SouthCar] < arrival[Pedestrian];
constraint arrival[SouthCar] < arrival[EastCar];

% Clue 7: North car and West car arrive at same moment, after Pedestrian and East car
constraint arrival[NorthCar] = arrival[WestCar];
constraint arrival[NorthCar] > arrival[Pedestrian];
constraint arrival[NorthCar] > arrival[EastCar];

% Rule 2: Cars/pedestrian go in order of arrival (unless tied)
% If arrival[A] < arrival[B], then order[A] < order[B]
constraint forall(a, b in ENTITY where a != b)(
  arrival[a] < arrival[b] -> order[a] < order[b]
);

% Rule 3: If two cars arrive at same moment, clockwise priority (N, E, S, W)
% Between Pedestrian and East car (same arrival), Pedestrian goes first (Rule 1 already handles this)

% Between North car and West car (same arrival):
% North comes before West in clockwise order, so North goes first
constraint order[NorthCar] < order[WestCar];

include "globals.mzn";

enum OUTCOME = {Denied, Approved, CounterOffer};

% Given facts
int: priya_credit = 680;
int: sam_credit = 750;
int: combined_income = 9000;
int: combined_debt = 3200;
bool: exceeds_policy_limit = true;

% Decision variable
var OUTCOME: outcome;

% Rule 1: Credit tier uses lower score; if below 600, denied
int: credit_tier = min(priya_credit, sam_credit);
constraint (credit_tier < 600) -> (outcome = Denied);

% Rule 2: DTI ratio = combined_debt / combined_income; if exceeds 43%, denied
float: dti_ratio = int2float(combined_debt) / int2float(combined_income);
constraint (dti_ratio > 0.43) -> (outcome = Denied);

% Rule 3: If not denied and within policy limits, approved
constraint (credit_tier >= 600 /\ dti_ratio <= 0.43 /\ not exceeds_policy_limit) -> (outcome = Approved);

% Rule 4: If not denied but exceeds policy limits, counter-offer
constraint (credit_tier >= 600 /\ dti_ratio <= 0.43 /\ exceeds_policy_limit) -> (outcome = CounterOffer);

solve satisfy;

include "globals.mzn";

enum DRUG = {DrugA, DrugB, DrugC};
array[DRUG] of var {9, 11, 16}: drugTime;

constraint alldifferent(drugTime);

% Constraint 1: Drug B must be taken at least 4 hours after Drug A
constraint drugTime[DrugB] >= drugTime[DrugA] + 4;

% Constraint 2: Drug C must be taken at least 2 hours away from any meal
% Meals are at 8am and 1pm (13:00)
constraint abs(drugTime[DrugC] - 8) >= 2;
constraint abs(drugTime[DrugC] - 13) >= 2;

solve satisfy;

