enum POSITION = {First, Second, Third, Fourth, Fifth};
enum COLOR = {Blue, Green, Red, White, Yellow};
enum NATIONALITY = {Brit, Dane, German, Norwegian, Swede};
enum DRINK = {Beer, Coffee, Milk, Tea, Water};
enum SMOKE = {Bluemaster, Dunhill, Pallmall, Prince, Blend};
enum PET = {Birds, Cats, Dogs, Fish, Horses};

array[POSITION] of var COLOR: color;
array[POSITION] of var NATIONALITY: nationality;
array[POSITION] of var DRINK: drink;
array[POSITION] of var SMOKE: smoke;
array[POSITION] of var PET: pet;

constraint alldifferent(color);
constraint alldifferent(nationality);
constraint alldifferent(drink);
constraint alldifferent(smoke);
constraint alldifferent(pet);

% The Brit lives in the red house
constraint exists(p in POSITION)(nationality[p] = Brit /\ color[p] = Red);

% The Swede keeps dogs
constraint exists(p in POSITION)(nationality[p] = Swede /\ pet[p] = Dogs);

% The Dane drinks tea
constraint exists(p in POSITION)(nationality[p] = Dane /\ drink[p] = Tea);

% The green house is immediately to the left of the white house
constraint exists(p in POSITION)(p != Fifth /\ color[p] = Green /\ color[enum_next(POSITION, p)] = White);

% The owner of the green house drinks coffee
constraint exists(p in POSITION)(color[p] = Green /\ drink[p] = Coffee);

% The person who smokes Pallmall keeps birds
constraint exists(p in POSITION)(smoke[p] = Pallmall /\ pet[p] = Birds);

% The owner of the yellow house smokes Dunhill
constraint exists(p in POSITION)(color[p] = Yellow /\ smoke[p] = Dunhill);

% The man in the center house drinks milk
constraint drink[Third] = Milk;

% The Norwegian lives in the first house
constraint nationality[First] = Norwegian;

% The man who smokes Blend lives next to the one who keeps cats
constraint exists(p in POSITION)(smoke[p] = Blend /\ exists(q in POSITION)(pet[q] = Cats /\ abs(enum_to_int(p) - enum_to_int(q)) = 1));

% The man who keeps horses lives next to the one who smokes Dunhill
constraint exists(p in POSITION)(pet[p] = Horses /\ exists(q in POSITION)(smoke[q] = Dunhill /\ abs(enum_to_int(p) - enum_to_int(q)) = 1));

% The man who smokes Bluemaster drinks beer
constraint exists(p in POSITION)(smoke[p] = Bluemaster /\ drink[p] = Beer);

% The German smokes Prince
constraint exists(p in POSITION)(nationality[p] = German /\ smoke[p] = Prince);

% The Norwegian lives next to the blue house
constraint exists(p in POSITION)(nationality[p] = Norwegian /\ exists(q in POSITION)(color[q] = Blue /\ abs(enum_to_int(p) - enum_to_int(q)) = 1));

% The man who smokes Blend has a neighbor who drinks water
constraint exists(p in POSITION)(smoke[p] = Blend /\ exists(q in POSITION)(drink[q] = Water /\ abs(enum_to_int(p) - enum_to_int(q)) = 1));

